// Compatible con chat trigger y webhook
const input = $input.first().json;

// Detectar mensaje y sessionId del trigger
let message, sessionId;

// Chat trigger: chatInput + sessionId directo
// Webhook: body.message + body.sessionId
if ($('Chat Trigger').first().json.chatInput) {
  message = $('Chat Trigger').first().json.chatInput;
  sessionId = $('Chat Trigger').first().json.sessionId || 'default';
} else if (input.body) {
  message = input.body.message || input.body.chatInput;
  sessionId = input.body.sessionId || input.body.idConversation;
} else {
  message = input.message || '';
  sessionId = input.sessionId || input.session_id || 'default';
}

// Buscar si Cargar Estado trajo algo
let dbState = null;
try {
  const rows = $('Cargar Estado').all();
  if (rows.length > 0 && rows[0].json.session_id) {
    dbState = rows[0].json;
  }
} catch(e) {}

// Si no hay state en DB, crear default
const state = dbState || {
  session_id: sessionId,
  paso: 1,
  dni: null,
  nombre: null,
  id_cliente: null,
  sucursal_code: null,
  sucursal_nombre: null,
  fecha_desde: null,
  fecha_hasta: null,
  modelo_code: null,
  categoria_code: null,
  precio_total: null,
  adicionales: null
};

return [{
  json: {
    ...state,
    message: message,
    sessionId: state.session_id || sessionId
  }
}];

const input = $input.first().json;
const prev = $('Preparar Contexto').first().json;
const agentOutput = input.output || '';

let dni = prev.dni;
let nombre = prev.nombre;
let id_cliente = prev.id_cliente;
let paso = 1;

// Método 1: tag estructurado
const match = agentOutput.match(/\[CLIENTE:\s*dni=([^,]+),\s*nombre=([^,]+),\s*id_cliente=([^\]]+)\]/);
if (match) {
  dni = match[1].trim();
  nombre = match[2].trim();
  id_cliente = match[3].trim() === 'null' ? null : match[3].trim();
  paso = 2;
}

// Método 2: intermediateSteps como fallback
if (paso === 1 && input.intermediateSteps) {
  for (const step of input.intermediateSteps) {
    if (step.action?.tool === 'get_customer_p1' && step.observation) {
      try {
        const obs = typeof step.observation === 'string' ? JSON.parse(step.observation) : step.observation;
        if (obs.id || obs.Id) {
          id_cliente = obs.id || obs.Id;
          nombre = obs.Name || obs.nombre || nombre;
          dni = obs.DocumentId || obs.dni || dni;
          paso = 2;
        }
      } catch(e) {}
    }
  }
}

const cleanResponse = agentOutput.replace(/\[CLIENTE:[^\]]+\]/, '').trim();

return [{ json: {
  session_id: prev.session_id || prev.sessionId,
  paso,
  dni,
  nombre,
  id_cliente,
  sucursal_code: prev.sucursal_code,
  sucursal_nombre: prev.sucursal_nombre,
  fecha_desde: prev.fecha_desde,
  fecha_hasta: prev.fecha_hasta,
  modelo_code: prev.modelo_code,
  categoria_code: prev.categoria_code,
  precio_total: prev.precio_total,
  adicionales: prev.adicionales,
  agent_response: cleanResponse
} }];

