const input = $input.first().json;

// Intentar traer datos del evaluador anterior (encadenado)
let prev = $('Preparar Contexto').first().json;
try {
  const paso1Data = $('Evaluar Paso 1').first().json;
  // Mergear: los datos del paso 1 pisan los de Preparar Contexto
  prev = { ...prev, ...paso1Data };
  // Sacar agent_response del paso anterior para no pisar
  delete prev.agent_response;
} catch(e) {}

const agentOutput = input.output || '';

let sucursal_code = prev.sucursal_code;
let sucursal_nombre = prev.sucursal_nombre;
let paso = 2;

// Prefix del paso 1 si viene encadenado
let prefix = '';
try {
  const paso1Response = $('Evaluar Paso 1').first().json.agent_response;
  if (paso1Response) prefix = paso1Response + '\n\n';
} catch(e) {}

// Método 1: tag estructurado
const match = agentOutput.match(/\[SUCURSAL:\s*code=([^,]+),\s*nombre=([^\]]+)\]/);
if (match) {
  sucursal_code = match[1].trim();
  sucursal_nombre = match[2].trim();
  paso = 3;
}

// Método 2: intermediateSteps como fallback
if (paso === 2 && input.intermediateSteps) {
  for (const step of input.intermediateSteps) {
    if (step.action?.tool === 'set_sucursal_p2' && step.observation) {
      try {
        const obs = typeof step.observation === 'string' ? JSON.parse(step.observation) : step.observation;
        if (obs.sucursal_code) {
          sucursal_code = obs.sucursal_code;
          sucursal_nombre = obs.sucursal_nombre || sucursal_nombre;
          paso = 3;
        }
      } catch(e) {}
    }
  }
}

const cleanResponse = agentOutput.replace(/\[SUCURSAL:[^\]]+\]/, '').trim();

return [{ json: {
  session_id: prev.session_id || prev.sessionId,
  paso,
  dni: prev.dni, nombre: prev.nombre, id_cliente: prev.id_cliente,
  sucursal_code, sucursal_nombre,
  fecha_desde: prev.fecha_desde, fecha_hasta: prev.fecha_hasta,
  modelo_code: prev.modelo_code, categoria_code: prev.categoria_code,
  precio_total: prev.precio_total, adicionales: prev.adicionales,
  agent_response: prefix + cleanResponse
} }];

