const input = $input.first().json;
const prev = $('Preparar Contexto').first().json;
const agentOutput = input.output || input.text || '';

let modelo_code = prev.modelo_code;
let categoria_code = prev.categoria_code;
let paso = 5;

const toolOutput = input.intermediateSteps || [];
for (const step of toolOutput) {
  if (step.action?.tool === 'set_modelo_p5' && step.observation) {
    try {
      const obs = typeof step.observation === 'string' ? JSON.parse(step.observation) : step.observation;
      if (obs.modelo_code) { modelo_code = obs.modelo_code; categoria_code = obs.categoria_code || obs.category; }
    } catch(e) {
      const obsText = String(step.observation);
      const mc = obsText.match(/modelo_code["']?\s*[:=]\s*["']?(\d+)/);
      if (mc) modelo_code = mc[1];
      const cc = obsText.match(/categor[iy]a?_code["']?\s*[:=]\s*["']?(\d+)/);
      if (cc) categoria_code = cc[1];
    }
  }
}

if (modelo_code && categoria_code) paso = 6;

return [{ json: {
  session_id: prev.session_id || prev.sessionId,
  paso,
  dni: prev.dni, nombre: prev.nombre, id_cliente: prev.id_cliente,
  sucursal_code: prev.sucursal_code, sucursal_nombre: prev.sucursal_nombre,
  fecha_desde: prev.fecha_desde, fecha_hasta: prev.fecha_hasta,
  modelo_code, categoria_code,
  precio_total: prev.precio_total, adicionales: prev.adicionales,
  agent_response: agentOutput
} }];

const prev = $('Preparar Contexto').first().json;
const precioResult = $('Fetch Precio').first().json;

let precio_total = null;
try {
  if (precioResult.total) precio_total = precioResult.total;
  else if (precioResult.price) precio_total = precioResult.price;
  else precio_total = JSON.stringify(precioResult);
} catch(e) { precio_total = String(precioResult); }

const response = `El precio total de tu reserva es de $${precio_total}. ¿Querés agregar algún adicional como silla para bebé o conductor adicional? Si no, seguimos con la confirmación.`;

return [{ json: {
  session_id: prev.session_id || prev.sessionId,
  paso: 7,
  dni: prev.dni, nombre: prev.nombre, id_cliente: prev.id_cliente,
  sucursal_code: prev.sucursal_code, sucursal_nombre: prev.sucursal_nombre,
  fecha_desde: prev.fecha_desde, fecha_hasta: prev.fecha_hasta,
  modelo_code: prev.modelo_code, categoria_code: prev.categoria_code,
  precio_total,
  adicionales: prev.adicionales,
  agent_response: response
} }];

const input = $input.first().json;
const prev = $('Preparar Contexto').first().json;
const agentOutput = input.output || input.text || '';

let adicionales = prev.adicionales;
let paso = 7;

const matchNone = agentOutput.match(/\[ADICIONALES:\s*ninguno\]/);
const matchSome = agentOutput.match(/\[ADICIONALES:\s*(.+?)\]/);

if (matchNone) {
  adicionales = '[]';
  paso = 8;
} else if (matchSome && !matchSome[1].includes('ninguno')) {
  const items = matchSome[1].split(',').map(s => ({ Name: s.trim() }));
  adicionales = JSON.stringify(items);
  paso = 8;
}

const cleanResponse = agentOutput.replace(/\[ADICIONALES:[^\]]+\]/, '').trim();

return [{ json: {
  session_id: prev.session_id || prev.sessionId,
  paso,
  dni: prev.dni, nombre: prev.nombre, id_cliente: prev.id_cliente,
  sucursal_code: prev.sucursal_code, sucursal_nombre: prev.sucursal_nombre,
  fecha_desde: prev.fecha_desde, fecha_hasta: prev.fecha_hasta,
  modelo_code: prev.modelo_code, categoria_code: prev.categoria_code,
  precio_total: prev.precio_total,
  adicionales,
  agent_response: cleanResponse
} }];

const prev = $('Preparar Contexto').first().json;
const msg = prev.message?.toLowerCase() || '';

// Check if client confirms
const confirms = ['si', 'sí', 'confirmo', 'dale', 'ok', 'perfecto', 'listo', 'va', 'vamos'].some(w => msg.includes(w));

if (!confirms) {
  // Show summary and ask for confirmation
  const adicionales = prev.adicionales ? JSON.parse(prev.adicionales) : [];
  const addText = adicionales.length > 0 ? adicionales.map(a => a.Name).join(', ') : 'Sin adicionales';

  const summary = `Perfecto, te confirmo tu reserva:\n\n📍 Sucursal: ${prev.sucursal_nombre}\n📅 Retiro: ${prev.fecha_desde}\n📅 Devolución: ${prev.fecha_hasta}\n🚗 Vehículo: modelo seleccionado (o similar)\n💰 Precio: $${prev.precio_total}\n➕ Adicionales: ${addText}\n\n¿Confirmás?`;

  return [{ json: {
    ...prev,
    paso: 8,
    agent_response: summary,
    confirmed: false
  } }];
}

// Client confirmed
return [{ json: {
  ...prev,
  paso: 9,
  confirmed: true
} }];

const prev = $input.first().json;
const result = $('Enviar Solicitud').first().json;

let numero = result.numero || result.id || result.reservation_id || 'N/A';

const adicionales = prev.adicionales ? JSON.parse(prev.adicionales) : [];
const addText = adicionales.length > 0 ? adicionales.map(a => a.Name).join(', ') : 'Sin adicionales';

const response = `✅ ¡Reserva confirmada!\n\n🔢 Número de reserva: ${numero}\n📍 Retiro: ${prev.sucursal_nombre} – ${prev.fecha_desde}\n📍 Devolución: ${prev.sucursal_nombre} – ${prev.fecha_hasta}\n🚗 Vehículo: (o similar)\n➕ Adicionales: ${addText}\n💰 Total: $${prev.precio_total}\n\n¡Te esperamos!`;

return [{ json: {
  ...prev,
  paso: 9,
  agent_response: response
} }];

// Output compatible con When chat message received
const response = $('Merge Resultados').first().json.agent_response|| 'Hubo un error, ¿querés hablar con un asesor?';
return [{ json: { output: response } }];

// Merge node - collects output from all evaluators
const items = $input.all();
if (items.length > 0) {
  const data = items[0].json;
  // Remove agent_response from state before saving, keep it for response
  const { agent_response, confirmed, message, sessionId, ...stateToSave } = data;
  return [{ json: { ...stateToSave, agent_response } }];
}
return items;

const sucursales = $('Fetch Sucursales').all().map(s => s.json);
const ctx = $('Preparar Contexto').first().json;

return [{
  json: {
    ...ctx,
    sucursales: sucursales
  }
}];
